def f(I):
    I=np.array(I); m=I!=0; H,W=m.shape
    seen=np.zeros_like(m); boxes=[]
    for i in range(H):
        for j in range(W):
            if m[i,j] and not seen[i,j]:
                st=[(i,j)]; rs=[]
                while st:
                    p=st.pop(); rs.append(p)
                    seen[p]=True
                    for dp,dq in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=p[0]+dp,p[1]+dq
                        if 0<=ni<H and 0<=nj<W and m[ni,nj] and not seen[ni,nj]:
                            st.append((ni,nj))
                rows_=sorted({p[0] for p in rs}); cols_=sorted({p[1] for p in rs})
                boxes.append((rows_[0],cols_[0],rows_[-1],cols_[-1]))
    boxes.sort()
    A=I[boxes[0][0]:boxes[0][2]+1,boxes[0][1]:boxes[0][3]+1]
    B=I[boxes[1][0]:boxes[1][2]+1,boxes[1][1]:boxes[1][3]+1]
    y,x=A.shape
    best=None
    for dr in range(-(y-1),y):
        for dc in range(-(x-1),x):
            sB=B[dr:dr+y,dc:dc+x]
            if sB.size==0 or sB.shape!=(y,x): continue
            n=int((A==sB).sum())
            if best is None or n>best[0]: best=(n,dr,dc)
    n,dr,dc=best
    D=A!=B[dr:dr+y,dc:dc+x]
    rows=[i for i in range(y) if any(D[i])]; cols=[j for j in range(x) if any(D[:,j])]
    return [[8 if D[i,j] else 0 for j in cols] for i in rows]

