                rows_=sorted({p for p,q in rs}); cols_=sorted({q for p,q in rs})
                boxes.append((min(rows_),min(cols_),max(rows_),max(cols_)))
    return sorted(boxes,key=lambda b:(b[2]-b[0])*(b[3]-b[1]), reverse=True)
